from flask import Flask, abort, url_for

app = Flask(__name__)

@app.route("/")
def home():
    return "<h1>Hello, Flask!</h1>"

@app.route("/user/<username>")
def profile(username):
    return f"Profile of {username}"

@app.route("/post/<int:post_id>")
def post(post_id):
    if post_id > 100:
        abort(404)
    return {"id": post_id, "title": f"Post {post_id}"}      # dict -> JSON

@app.route("/links")
def links():
    return url_for("profile", username="asha")             # "/user/asha"

@app.errorhandler(404)
def not_found(error):
    return "<h1>Page not found</h1>", 404

if __name__ == "__main__":
    app.run(debug=True)

from flask import Flask, request, jsonify, redirect, url_for, make_response, flash

app = Flask(__name__)
app.secret_key = "change-me"

@app.route("/search")
def search():
    q = request.args.get("q", "").strip()
    page = request.args.get("page", 1, type=int)
    return jsonify(query=q, page=page)

@app.route("/contact", methods=["GET", "POST"])
def contact():
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        if not name:
            flash("Name is required")
            return redirect(url_for("contact"))
        flash(f"Thanks {name}!")
        return redirect(url_for("contact"))
    return """<form method="post"><input name="name"><button>Send</button></form>"""

@app.post("/api/echo")
def echo():
    data = request.get_json(silent=True) or {}
    return jsonify(received=data), 201

@app.route("/theme/<name>")
def theme(name):
    resp = make_response(redirect(url_for("search")))
    resp.set_cookie("theme", name, max_age=60 * 60 * 24 * 30, httponly=True)
    return resp

from flask import Flask, render_template, redirect, url_for, flash
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Email, Length, EqualTo, ValidationError

app = Flask(__name__)
app.config["SECRET_KEY"] = "dev-only-secret"

TAKEN = {"asha@example.com"}

class RegisterForm(FlaskForm):
    email = StringField("Email", validators=[DataRequired(), Email()])
    password = PasswordField("Password", validators=[DataRequired(), Length(min=8)])
    confirm = PasswordField("Confirm", validators=[EqualTo("password", "Passwords must match")])
    submit = SubmitField("Register")

    def validate_email(self, field):
        if field.data.lower() in TAKEN:
            raise ValidationError("Email already registered")

@app.route("/register", methods=["GET", "POST"])
def register():
    form = RegisterForm()
    if form.validate_on_submit():
        flash("Account created")
        return redirect(url_for("register"))
    return render_template("register.html", form=form)

from flask import Flask, jsonify, request, abort

app = Flask(__name__)
tasks = {1: {"id": 1, "title": "Learn Flask", "done": False}}
next_id = 2

@app.get("/api/v1/tasks")
def list_tasks():
    done = request.args.get("done")
    items = list(tasks.values())
    if done is not None:
        items = [t for t in items if t["done"] == (done.lower() == "true")]
    return jsonify(items)

@app.post("/api/v1/tasks")
def create_task():
    global next_id
    data = request.get_json(silent=True) or {}
    title = str(data.get("title", "")).strip()
    if not title:
        return jsonify(error="title is required"), 400
    task = {"id": next_id, "title": title, "done": False}
    tasks[next_id] = task
    next_id += 1
    return jsonify(task), 201

@app.patch("/api/v1/tasks/<int:task_id>")
def update_task(task_id):
    task = tasks.get(task_id) or abort(404)
    task.update({k: v for k, v in (request.get_json() or {}).items() if k in ("title", "done")})
    return jsonify(task)

@app.delete("/api/v1/tasks/<int:task_id>")
def delete_task(task_id):
    if tasks.pop(task_id, None) is None:
        abort(404)
    return "", 204

@app.errorhandler(404)
def not_found(e):
    return jsonify(error="not found"), 404

from flask import Flask, request, redirect, url_for, render_template, flash
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "load-from-environment"

login_manager = LoginManager(app)
login_manager.login_view = "login"

class User(UserMixin):
    def __init__(self, id, email, password_hash):
        self.id, self.email, self.password_hash = id, email, password_hash

USERS = {"1": User("1", "asha@example.com", generate_password_hash("secret123"))}

@login_manager.user_loader
def load_user(user_id):
    return USERS.get(user_id)

@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        email = request.form.get("email", "")
        password = request.form.get("password", "")
        user = next((u for u in USERS.values() if u.email == email), None)
        if user and check_password_hash(user.password_hash, password):
            login_user(user)
            return redirect(url_for("dashboard"))
        flash("Invalid credentials")
    return render_template("login.html")

@app.route("/dashboard")
@login_required
def dashboard():
    return f"Welcome {current_user.email}"

@app.route("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))
